"use client";

import "../../styles/teum-base.css";
import "../../styles/components/collapsible.css";
import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible";
import { CaretDown } from "@phosphor-icons/react";
import type { ReactNode } from "react";
import { cn } from "../../lib/cn";

export const Collapsible = CollapsiblePrimitive.Root;

export type CollapsibleContentProps = CollapsiblePrimitive.Panel.Props & { children?: ReactNode };

export function CollapsibleTrigger({ className, children, ...props }: CollapsiblePrimitive.Trigger.Props) {
  return (
    <CollapsiblePrimitive.Trigger className={cn("teum-collapsible__trigger", className)} {...props}>
      <span>{children}</span>
      <CaretDown aria-hidden="true" />
    </CollapsiblePrimitive.Trigger>
  );
}

export function CollapsibleContent({ className, children, ...props }: CollapsibleContentProps) {
  return (
    <CollapsiblePrimitive.Panel className={cn("teum-collapsible__panel", className)} {...props}>
      <div className="teum-collapsible__content">{children}</div>
    </CollapsiblePrimitive.Panel>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-collapsible__trigger { display: flex; width: 100%; min-height: 38px; align-items: center; justify-content: space-between; gap: 16px; padding: 0 11px; border: 0; border-radius: var(--teum-radius-md); background: var(--teum-bg-subtle); color: var(--teum-fg-default); font-size: var(--teum-type-ui); font-weight: 560; text-align: left; cursor: pointer; transition: background-color var(--teum-hover-duration), color var(--teum-hover-duration); }

.teum-collapsible__trigger svg { width: 14px; height: 14px; flex: 0 0 auto; color: var(--teum-fg-subtle); transform: rotate(0); transition: transform 160ms var(--teum-ease-out); }

.teum-collapsible__trigger[data-panel-open] svg { transform: rotate(180deg); }

.teum-collapsible__trigger:focus-visible { outline: 2px solid var(--teum-focus-control); outline-offset: 2px; }

.teum-collapsible__trigger[data-disabled] { color: var(--teum-fg-disabled); cursor: not-allowed; }

.teum-collapsible__panel {
  height: var(--collapsible-panel-height);
  overflow: hidden;
  transition: height var(--teum-enter-duration) var(--teum-ease-out);
}

.teum-collapsible__panel[data-starting-style],
.teum-collapsible__panel[data-ending-style] { height: 0; }

.teum-collapsible__panel[data-ending-style] { transition-duration: var(--teum-exit-duration); }

.teum-collapsible__content { padding: 12px 11px 2px; color: var(--teum-fg-muted); font-size: var(--teum-type-ui); line-height: 1.55; }

@media (hover: hover) and (pointer: fine) {
.teum-collapsible__trigger:not([data-disabled]):hover { background: var(--teum-hover); color: var(--teum-fg-default); }
}

@media (prefers-reduced-motion: reduce) {
.teum-collapsible__panel,
.teum-collapsible__trigger svg { transition-duration: 0.01ms; }
}
}
